using System.Collections.ObjectModel;
namespace VisionFramework;
// ProcessGroupOutputV44 clears mode1 primitives before append; mode0 retains them.
// Images are replaced every round. Managed lists are independent of the native ABI.
internal sealed class GroupOutputAccumulator(ProcedureDocument body){
 readonly Dictionary<string,List<PortValue>> displays=new(StringComparer.Ordinal);int displayCount;
 readonly Dictionary<string,int> elementCounts=new(StringComparer.Ordinal);
 readonly Dictionary<string,List<PortValue>> accumulated=new(StringComparer.Ordinal);int count;
 public void Add(ExecutionSessionResult iteration){foreach(var spec in body.Configuration.Displays){if(!iteration.WorkflowDisplays.TryGetValue(spec.Name,out var values))continue;if(!displays.TryGetValue(spec.Name,out var frames))displays[spec.Name]=frames=new();if(!spec.Accumulate||spec.Kind==DataKind.GrayImage){displayCount-=frames.Count;frames.Clear();}if(values.Count>1000000-displayCount)throw new InvalidOperationException("Independent display frame limit is 1000000.");displayCount+=values.Count;frames.AddRange(values);}foreach(var spec in body.Configuration.Outputs.Where(o=>o.Accumulate&&GroupBreak.Accumulatable(o.Kind))){if(!iteration.WorkflowOutputs.TryGetValue(spec.Name,out var value))continue;int length=value.Cardinality==ValueCardinality.Scalar?1:value.Kind switch{DataKind.Integer=>value.As<IReadOnlyList<long>>().Count,DataKind.Number=>value.As<IReadOnlyList<double>>().Count,_=>value.As<IReadOnlyList<string>>().Count};if(length>1000000-count)throw new InvalidOperationException("Independent accumulated output element limit is 1000000.");count+=length;elementCounts[spec.Name]=elementCounts.GetValueOrDefault(spec.Name)+length;if(!accumulated.TryGetValue(spec.Name,out var list))accumulated[spec.Name]=list=new();list.Add(value);}}
 public PortValue ReadSelfElement(string name,int index,ExecutionSessionResult? last){
  var spec=body.Configuration.Outputs.SingleOrDefault(o=>o.Name==name)??throw new InvalidDataException("Group self output no longer exists.");
  if(!spec.Accumulate||!GroupBreak.Accumulatable(spec.Kind))return GroupBreak.Element(last?.WorkflowOutputs.GetValueOrDefault(name)??throw new InvalidDataException("Group self output unavailable."),index);
  if(index<0||index>=elementCounts.GetValueOrDefault(name))throw new InvalidDataException("Group self output element is unavailable.");
  foreach(var value in accumulated[name]){int length=value.Cardinality==ValueCardinality.Scalar?1:value.Kind switch{DataKind.Integer=>value.As<IReadOnlyList<long>>().Count,DataKind.Number=>value.As<IReadOnlyList<double>>().Count,_=>value.As<IReadOnlyList<string>>().Count};if(index<length)return GroupBreak.Element(value,index);index-=length;}throw new InvalidDataException("Group self output unavailable.");
 }
 public IReadOnlyDictionary<string,IReadOnlyList<PortValue>> FinishDisplays()=>new ReadOnlyDictionary<string,IReadOnlyList<PortValue>>(displays.ToDictionary(p=>p.Key,p=>(IReadOnlyList<PortValue>)Array.AsReadOnly(p.Value.ToArray()),StringComparer.Ordinal));
 public IReadOnlyDictionary<string,PortValue> Finish(ExecutionSessionResult? last){var outputs=last?.WorkflowOutputs.ToDictionary(p=>p.Key,p=>p.Value,StringComparer.Ordinal)??new(StringComparer.Ordinal);foreach(var spec in body.Configuration.Outputs.Where(o=>o.Accumulate&&GroupBreak.Accumulatable(o.Kind))){var values=accumulated.GetValueOrDefault(spec.Name)??[];outputs[spec.Name]=spec.Kind switch{DataKind.Integer=>PortValue.IntegerArray(values.SelectMany(v=>v.Cardinality==ValueCardinality.Scalar?new[]{v.As<long>()}:v.As<IReadOnlyList<long>>())),DataKind.Number=>PortValue.NumberArray(values.SelectMany(v=>v.Cardinality==ValueCardinality.Scalar?new[]{v.As<double>()}:v.As<IReadOnlyList<double>>())),_=>PortValue.TextArray(values.SelectMany(v=>v.Cardinality==ValueCardinality.Scalar?new[]{v.As<string>()}:v.As<IReadOnlyList<string>>()))};}return new ReadOnlyDictionary<string,PortValue>(outputs);}
}
